     blip=function(t){ rec.push('b:'+t); };
     foley=function(r){ rec.push('f:'+r); return true; };
     sndUi=function(k){ rec.push('u:'+k); return true; };
     // every belt key, one by one: never the pick chirp
     sl=hotbarSlots(); n=sl.length;
